def section_heading(kicker,title,description=''):
    return f'<div class="section-top"><p class="eyebrow">{kicker}</p><div><h2>{title}</h2>{f"<p class=lead>{description}</p>" if description else ""}</div></div>'

def header(path):
    links=[('Fidelización','/fidelizacion/'),('Comercios','/comercios/'),('Automatizaciones','/automatizaciones/'),('Demos','/#demos')]
    nav=''.join(f'<a href="{u}"{chr(32)+"aria-current=page" if u==path else ""}>{n}</a>' for n,u in links)
