home=f'''<section class="hero"><div class="wrap"><div class="hero-grid"><div class="reveal"><p class="eyebrow">Fidelización que impulsa negocios locales</p><h1>Aumentá tus ventas<br>sin invertir en<br><em>publicidad.</em></h1><p class="lead">Convertí a quienes ya te compraron en clientes que vuelven. Tu programa de fidelización con Apple Wallet, Google Wallet, notificaciones y email.</p><div class="actions">{button('Quiero mi demo','#contacto')}{button('Cómo funciona','#como-funciona','secondary')}</div><p class="hero-note">Te contactamos personalmente y armamos una propuesta para tu negocio.</p></div>{home_visual}</div><div class="rail"><span><b>01</b> TU MARCA, SIEMPRE</span><span><b>02</b> SIN DESCARGAR OTRA APP</span><span><b>03</b> IMPLEMENTACIÓN A MEDIDA</span><span><b>04</b> ACOMPAÑAMIENTO DIRECTO</span></div></div></section><section class="section solutions" id="soluciones"><div class="wrap">{section_heading('Una relación, de punta a punta','Primero, que vuelvan.<br><span class="serif">Después, todo conectado.</span>','Fidelización como punto de partida. Catálogos y automatizaciones para acompañar el resto de tu operación.')} {product_cards()}</div></section><section class="section wallet-section" id="como-funciona"><div class="wrap split">{phone()}<div><p class="eyebrow">IMAN Fidelización · Wallet primero</p><h2>Estar cerca.<br>Incluso <span class="serif">después<br>de la compra.</span></h2><p class="lead">Creamos el Club de tu marca en Apple Wallet y Google Wallet. Tu cliente guarda su tarjeta y tiene a mano sus beneficios, puntos y novedades.</p><div class="wallet-labels"><span>Apple Wallet</span><span>Google Wallet</span></div><p class="small muted">Las notificaciones acercan las novedades de la tarjeta. Los mails desarrollan la propuesta y reactivan la relación. Una misma estrategia, con el canal adecuado para cada momento.</p><div class="actions">{button('Conocé IMAN Fidelización','/fidelizacion/')}</div></div></div></section><section class="section dark"><div class="wrap">{section_heading('IMAN Automatizaciones','Que el trabajo avance.<br><span class="serif">Sin hacerlo todo a mano.</span>','Tomamos una tarea concreta, conectamos tus herramientas y la convertimos en un proceso que podés seguir.')} {steps([('Detectamos la tarea','Qué se repite, cuánto tiempo lleva y dónde se pierde información.'),('Definimos las reglas','Qué puede resolverse solo y qué necesita tu aprobación.'),('Lo ponemos a funcionar','Desarrollo, integración y pruebas con tu operación.'),('Medimos y ajustamos','Un flujo documentado y un plan de acompañamiento.')])}<div class="actions">{button('Ver procesos y entregables','/automatizaciones/','light')}<a class="text-link" href="/automatizaciones/#compras">Automatizar compras <span aria-hidden="true">↗</span></a></div></div></section>{demo_gallery()}'''
