auto_faq=[('¿Qué recibo al contratar una automatización?','Un proceso con alcance acordado: mapa del flujo, reglas, conexiones necesarias, pruebas, documentación y una explicación de cómo operarlo. La propuesta aclara el soporte y mantenimiento incluidos.'),('¿Qué se puede automatizar?','Por ejemplo, ordenar consultas, preparar respuestas, registrar pedidos, hacer seguimientos o consolidar reportes. Primero verificamos los sistemas, permisos e interfaces disponibles para confirmar la viabilidad.'),('¿El agente decide y ejecuta sin preguntarme?','Definimos juntos los permisos. Las acciones sensibles, como comprometer precios, aprobar una compra o ejecutar un pago, pueden exigir tu aprobación. El proyecto especifica qué se automatiza y qué queda bajo control humano.'),('¿Qué herramientas se pueden conectar?','Evaluamos tus formularios, planillas, CRM, catálogo y sistemas de gestión. La conexión depende de sus APIs, permisos, condiciones y accesos. Los costos de servicios externos se detallan por separado cuando corresponda.'),('¿Pueden automatizar compras mayoristas?','Sí, desarrollamos proyectos para interpretar necesidades de compra, comparar propuestas y coordinar la operación bajo reglas. El ejemplo ilustra el recorrido; una integración productiva requiere sistemas conectados y un alcance específico.'),('¿Cómo se cotiza?','Separamos la implementación inicial del acompañamiento posterior. El presupuesto depende del número de flujos, conexiones, volumen y controles. El diagnóstico define entregables y criterios de aceptación antes de desarrollar.')]
auto=hero('IMAN Automatizaciones','Menos tareas.<br>Más tiempo para<br><span class="serif purple">hacer negocio.</span>','Desarrollamos automatizaciones y agentes de IA a medida. Partimos de un proceso concreto y lo entregamos conectado, probado y documentado.',(ROOT/'templates/negotiation.html').read_text(),'Contanos tu proceso',('Ver qué podemos resolver','#procesos'))
auto+='''<section class="section solutions" id="procesos"><div class="wrap">'''+section_heading('Casos concretos','Esto es lo que<br><span class="serif">podés dejar de hacer a mano.</span>')+'''<div class="case-list"><article class="case"><span class="num">01</span><h3>Consultas y<br>seguimiento comercial.</h3><div><p>Recibir una consulta, identificar la necesidad, registrarla y preparar el siguiente paso. Si hace falta criterio comercial, el flujo deriva a una persona.</p><p class="small"><b>Entregable:</b> ingreso conectado + registro + clasificación + seguimiento acordado.</p></div></article><article class="case"><span class="num">02</span><h3>Pedidos e<br>información ordenada.</h3><div><p>Pasar de mensajes y planillas dispersas a un pedido estructurado. Validar campos, detectar faltantes y preparar el registro en tu sistema.</p><p class="small"><b>Entregable:</b> captura de pedido + validaciones + integración disponible + registro de errores.</p></div></article><article class="case"><span class="num">03</span><h3>Avisos y<br>tareas operativas.</h3><div><p>Disparar acciones cuando cambia un estado: pedido listo, entrega confirmada o tarea pendiente. Tu equipo sabe qué pasó y qué necesita intervenir.</p><p class="small"><b>Entregable:</b> eventos definidos + reglas + avisos por canales acordados + historial.</p></div></article><article class="case"><span class="num">04</span><h3>Reportes para<br>tomar decisiones.</h3><div><p>Consolidar información de fuentes autorizadas y preparar un resumen periódico de ventas, consultas u operación. Sin armar el mismo reporte una y otra vez.</p><p class="small"><b>Entregable:</b> fuentes conectadas + métricas definidas + reporte y frecuencia acordados.</p></div></article></div></div></section>'''
auto+='<section class="section"><div class="wrap">'+section_heading('Una contratación concreta','Sabés qué vamos a hacer.<br><span class="serif">Y qué te llevás.</span>')+'''<div class="service-packages"><article class="package"><p class="eyebrow">01 / Diagnóstico</p><h3>Un proceso.<br>Un plan claro.</h3><p>Encontramos una tarea que valga la pena automatizar y definimos cómo comprobar que funciona.</p><ul><li>Mapa del proceso actual</li><li>Sistemas y datos necesarios</li><li>Reglas y aprobaciones</li><li>Alcance, propuesta y criterio de éxito</li></ul>'''+button('Evaluar mi proceso')+'''</article><article class="package"><p class="eyebrow">02 / Implementación</p><h3>Del plan<br>a la operación.</h3><p>Desarrollamos el flujo acordado y lo probamos con escenarios representativos antes de activarlo.</p><ul><li>Desarrollo e integraciones acordadas</li><li>Pruebas de casos y excepciones</li><li>Registro de acciones y errores</li><li>Documentación y puesta en marcha</li></ul>'''+button('Armar mi automatización')+'''</article><article class="package"><p class="eyebrow">03 / Acompañamiento</p><h3>Que siga<br>funcionando bien.</h3><p>Definimos un plan de seguimiento para mantener el proceso y evaluar mejoras.</p><ul><li>Revisión del funcionamiento</li><li>Atención de incidencias acordada</li><li>Ajustes dentro del alcance</li><li>Nuevos procesos cotizados por separado</li></ul>'''+button('Consultar acompañamiento')+'''</article></div><p class="small muted" style="margin-top:25px">Implementación y mantenimiento se presupuestan según alcance. Licencias, mensajería y consumo de servicios externos se identifican en la propuesta.</p></div></section>'''
auto+='<section class="section dark" id="compras"><div class="wrap">'+section_heading('IMAN / Compras mayoristas','Cuando tus procesos<br><span class="serif">necesitan conversar.</span>','Con IMAN Automatizaciones podés coordinar necesidades de compra, propuestas de proveedores y aprobaciones dentro de un mismo proceso.')+steps([('Contexto','Stock, necesidad de compra y condiciones de la empresa.'),('Comparación','Propuestas de proveedores bajo los mismos criterios.'),('Aprobación','Límites de precio, presupuesto y controles definidos.'),('Ejecución','Coordinación de la operación y trazabilidad del proceso.')])+f'<div class="actions">{button("Ver un ejemplo de compras","/automatizaciones/compras-demo/","light",True)}<a class="text-link" href="#contacto">Evaluar un piloto B2B ↗</a></div><p class="small muted" style="margin-top:24px">La negociación, adjudicación y cualquier integración de pagos se evalúan por proyecto, con autorizaciones y límites explícitos.</p></div></section>'
